  Ru = `오른쪽 버튼을 눌러 페이지 검토 요청을 제출할 수 있습니다. 검토와 승인 및 기타 필요한 변경 사항을 수정하는데 소요되는 시간을 고려하여 게시 예정 날짜를 기준으로 최소 7일 정도의 여유를 두고 제출하세요.`,
