  Hu = `검토 요청`,
  Uu = `할인 페이지 게시 승인을 위한 검토 요청 티켓을 생성합니다. 할인 페이지에 최종 아트워크와 할인하려는 모든 게임이 포함된 경우 검토를 요청하세요.`,
  Wu = `이렇게 하면 Valve에 판매 페이지 검토를 요청하는 Steamworks 지원 티켓이 생성됩니다. 아트와 메시지가 최종적으로 준비되고, 게임 목록이 완성된 후에만 검토를 요청해야 합니다.`,
