  Gz = `꾸러미 할인 외에도 이 꾸러미에 포함된 1개 이상의 제품에 기간 한정 할인이 적용되어 총 할인율이 더 높아집니다.`,
  Kz = `이 게임이 포함된 꾸러미의 일부 제품을 이미 소유하고 있으므로 더 저렴한 가격으로 꾸러미를 완성할 수 있습니다.`,
  qz = `이 게임이 포함된 꾸러미의 일부 제품을 이미 소유하고 있으며, 기간 한정 할인이 추가로 적용됩니다.`,
  Jz = `정가에 적용되는 기간 한정 할인입니다.`,
  Yz = `스트리밍을 %1$s분 시청하고, 이벤트가 종료될 때 개발사에서 드롭되는 아이템을 획득하세요!`,
  Xz = `스트리밍을 %1$s분 시청하고, 이벤트가 종료될 때 %2$s에서 드롭되는 아이템을 획득하세요!`,
  Zz = `스트리밍을 %1$s시간 시청하고, 이벤트가 종료될 때 개발사에서 드롭되는 아이템을 획득하세요!`,
  Qz = `스트리밍을 %1$s시간 시청하고, 이벤트가 종료될 때 %2$s에서 드롭되는 아이템을 획득하세요!`,
  $z = `드롭에 관한 자세한 정보는 여기에서 확인하세요.`,
