  oB = `지금부터 %1$s까지`,
  sB = `이벤트 둘러보기`,
  cB = `이 이벤트에서 추천하는 게임`,
  lB = `이 이벤트에 참가하는 다른 게임`,
  uB = `이 이벤트에 참가하는 다른 게임`,
  dB = `이 타사 이벤트는 %1$s에서 제공합니다.`,
  fB = `이 타사 이벤트는 %1$s 및 %2$s에서 제공합니다.`,
  pB = `주최사는 해당 이벤트를 진행하는 타사의 정보를 입력해야 합니다.`,
  mB = `'true'로 설정하면 이벤트 주최사는 이벤트 진행사를 지정해야 합니다. 해당 내용은 고객 전용 할인 페이지에 표시되므로 고객에게 이벤트 진행사가 Valve가 아닌 타사임을 명확하게 알릴 수 있습니다.`,
  hB = `이벤트 주최사 이름 전체 삭제`,
  gB = `할인 이벤트 주최사에 대한 설명을 반드시 입력해야 합니다.`,
  _B = `추천한 큐레이터: %1$s`,
  vB = `내가 팔로우하는 큐레이터의 추천작`,
