  NB = `이 꾸러미에 있는 게임에 대한 사용자 평가 %2$s개 중 %1$s%가 긍정적입니다`,
  PB = `이 소프트웨어에 대한 사용자 평가 %2$s개 중 %1$s%가 긍정적입니다`,
