  IB = `이 하드웨어에 대한 사용자 평가 %2$s개 중 %1$s%가 긍정적입니다`,
  LB = `이 시리즈에 대한 사용자 평가 %2$s개 중 %1$s%가 긍정적입니다`,
  RB = `평가 점수: %1$s`,
  zB = `%2$s 평가 점수는 %1$s입니다.`,
  BB = `%1$s 평가: `,
  VB = `할인 혜택은 %1$s에 종료됩니다.`,
  HB = `%1$s까지 무료로 플레이하세요.`,
  UB = `월요일까지 무료로 플레이하세요.`,
  WB = `동적 공개 미리 보기`,
  GB = `아래 섹션에는 동적 공개 기능이 활성화되어 있습니다. 테스트를 시작하여 기능을 미리 볼 수 있으며, 미리 보기 탭을 닫으면 초기화됩니다.`,
  KB = `테스트 모드 시작`,
  qB = `원본 데이터를 지우고 모든 항목을 무작위로 공개합니다. 이 섹션은 %1$s초 후에 자동으로 새로고침됩니다.`,
  JB = `강제 서비스 호출`,
  YB = `%1$s일차 판매 보기`,
  XB = `Steam Play로`,
  ZB = `이 기기에서 실행`,
  QB = `이 게임에 적용 선택함`,
  $B = `모든 게임에 적용 선택함`,
  eV = `Valve 테스트가 선택`,
  tV = `<1>Steam Play</1>를 통해 이 컴퓨터에서 실행`,
  nV = `이 게임에 대해 내가 선택한 도구: %1$s`,
  rV = `Valve 테스트를 통해 선택된 도구: %1$s`,
  iV = `Steam 어워드`,
  aV = `후보작`,
  oV = `Steam 어워드 후보작`,
  sV = `지금 추천하세요. 투표는 12월에 진행됩니다.`,
  cV = `본 이벤트의 Steam 어워드는 막을 내렸습니다. 올해 가을 및 겨울 할인 기간에 진행될 연간 Steam 어워드를 확인하세요!`,
  lV = `%1$s년 12월`,
  uV = `버튼을 클릭해 %1$s에 투표하세요.`,
  dV = `%1$s 게임은 아래 부문의 후보작으로 선정되기를 기대하고 있습니다.`,
  fV = `%1$s 게임을 Steam 어워드 페이지의 수상 부문에 추천하려면 여기를 클릭하세요.`,
  pV = `후보작 추천이 종료되었습니다. 겨울 할인 기간 동안 투표하세요. 수상작은 1월 2일에 발표됩니다.`,
  mV = `투표가 종료되었습니다. 결과를 확인하려면 여기를 클릭하세요.`,
  hV = `추천 부문:`,
  gV = `내 추천작 보기`,
  _V = `%1$s 후보작으로 추천`,
  vV = `%1$s 후보작으로 추천했습니다.`,
  yV = `올해의 게임`,
  bV = `올해의 VR 게임`,
  xV = `어버이의 은혜`,
  SV = `함께하면 더 재밌어`,
  CV = `뛰어난 비주얼 스타일`,
  wV = `가장 혁신적인 게임플레이`,
  TV = `내가 못하는 최고의 게임`,
  EV = `최고의 사운드트랙`,
  DV = `압도적인 스토리를 자랑하는 게임`,
  OV = `부담 없이 즐기는 게임`,
  kV = `게임을 특정 부문으로 지정하는 대신에, 팬이 게임에 가장 적합한 부문을 직접 선택하도록 하세요. 이벤트에는 여전히 추천 페이지에 대한 링크가 포함됩니다.`,
  AV = `부문 없음`,
  jV = `몰입감 있는 게임 플레이, 흥미진진한 스토리, 잘 만들어진 캐릭터, 완벽한 디자인, 중독성 강한 멀티 플레이! 그 이유가 무엇이든 2020년 올해의 게임 수상작은 명작임이 틀림없습니다.`,
  MV = `올해의 VR 게임은 단순히 평범한 현실을 가장한 것만이 아닙니다. 이 게임은 현실성을 향상하고 VR이라는 매체를 이용하여 가상 영역의 경계를 넓혔습니다.`,
  NV = `이 게임은 출시된 지 좀 오랜 시간이 흘렀죠. 제작진과 개발팀은, 그들의 창의력으로 잉태된 아기 같은 이 게임을 공개된 이후 지금까지, 훌륭한 부모처럼 자신들의 창조물을 키워주고 지원해 왔습니다. 세월이 흐른 지금까지도 새로운 콘텐츠 업데이트가 끊이지 않는 게임입니다.`,
  PV = `어떤 게임은 혼자 플레이하면 뭔가 허전할 때가 있습니다. 친구가 날 좀 엄호해줬으면 하는 마음 때문일 수도 있고 친구를 골탕 먹이고 싶어서 그런 것일 수도 있죠. 어쨌든 이 게임은 친구들을 불러 모아 함께 낄낄대며 플레이하기 딱 좋은 게임입니다.`,
  FV = `이 게임의 비주얼 스타일은 현실 세계의 선명함을 동경할 필요도 없으며(숭고한 목적은 그렇지만요)… 게임 전체에 녹아 있는 독특한 모습과 느낌을 잘 묘사합니다.`,
  IV = `이 게임의 디자이너들은 창의적인 실험의 최전선에서 참신한 시각과 뇌를 깨우는 놀라움을 선사합니다. 이 게임은 이전에 한 번도 플레이한 적 없었던 새로움으로 즐거움, 영감 그리고 재미를 선사합니다.`,
  LV = `이 게임은 굳은 의지와 인내심에 보답하는 게임으로, 실의에 잘 빠지는 사람을 위한 것은 아닙니다. 이 게임은 우리가 사랑한 역대 초고난도의 게임입니다.`,
  RV = `주목받아 마땅한 이 영웅은 뛰어난 작곡으로 인정받아야 합니다. 최고의 OST입니다! `,
  zV = `이야기가 풍부한 게임만이 여러분을 만족시키는 날도 있죠. 이 게임이 바로 그런 게임입니다. 드라마처럼 우리의 시선을 사로잡고, 명성 있는 TV쇼처럼 잘 짜여 있습니다. 브라비시모! 저희에게 감동을 선사해 주셔서 감사합니다!`,
  BV = `이 게임은 바쁜 일상에 단비와도 같은 게임입니다. 잔잔하고 편안하며 모든 걱정을 녹여줄 것입니다. 이 게임은 당신에게 휴식을 선물할 것입니다.`,
  VV = `추천 게임을 바꾸시겠어요?`,
  HV = `각 부문당 1개의 게임만 추천할 수 있습니다. 이 부문에는 이미 %1$s 게임을 추천하셨습니다. %2$s 게임으로 추천 게임을 변경하시겠어요?`,
  UV = `투표`,
  WV = `투표 완료`,
  GV = `투표 완료`,
  KV = `투표 내용을 변경하시겠어요?`,
  qV = `각 부문당 1개의 게임에만 투표할 수 있습니다. 이 부문에는 이미 %1$s 게임에 투표하셨습니다. %2$s 게임으로 투표 내용을 변경하시겠어요?`,
  JV = `제한된 계정입니다. 추천 남용을 방지하기 위해, Steam에서 미화 5달러를 소비한 사용자만 Steam 어워드에 참여할 수 있습니다. 자세한 내용은 %1$s에서 확인하세요.`,
  YV = `제한된 계정입니다. 투표 남용을 방지하기 위해, Steam에서 미화 5달러를 소비한 사용자만 Steam 어워드에 참여할 수 있습니다. 자세한 내용은 %1$s에서 확인하세요.`,
