  SH = `내가 못하는 최고의 게임`,
  CH = `최고의 사운드트랙`,
  wH = `압도적인 스토리를 자랑하는 게임`,
  TH = `부담 없이 즐기는 게임`,
  EH = `어디서나 즐기기 좋은 최고의 게임`,
  DH = `몰입감 있는 게임플레이, 흥미진진한 스토리, 잘 만들어진 캐릭터, 완벽한 디자인, 중독성 강한 멀티플레이! 그 이유가 무엇이든 올해의 게임 수상작은 명작임이 틀림없습니다.`,
  OH = `올해의 VR 게임은 단순히 평범한 현실을 가장한 것만이 아닙니다. 이 게임은 현실성을 향상하고 VR이라는 매체를 이용하여 가상 영역의 경계를 넓혔습니다.`,
  kH = `이 게임은 출시된 지 좀 오랜 시간이 흘렀죠. 제작진과 개발팀은, 그들의 창의력으로 잉태된 아기 같은 이 게임을 공개된 이후 지금까지, 훌륭한 부모처럼 자신들의 창조물을 키워주고 지원해 왔습니다. 세월이 흐른 지금까지도 새로운 콘텐츠 업데이트가 끊이지 않는 게임입니다.`,
  AH = `어떤 게임은 혼자 플레이하면 뭔가 허전할 때가 있습니다. 친구가 날 좀 엄호해줬으면 하는 마음 때문일 수도 있고 친구를 골탕 먹이고 싶어서 그런 것일 수도 있죠. 어쨌든 이 게임은 친구들을 불러 모아 함께 낄낄대며 플레이하기 딱 좋은 게임입니다.`,
  jH = `이 게임의 비주얼 스타일은 현실 세계의 선명함을 동경할 필요도 없이(숭고한 목적은 그렇지만요)… 게임 전체에 녹아 있는 독특한 모습과 느낌을 잘 묘사합니다.`,
  MH = `이 게임의 디자이너들은 창의적인 실험의 최전선에서 참신한 시각과 뇌를 깨우는 놀라움을 선사합니다. 이 게임은 이전에 한 번도 플레이한 적 없었던 새로움으로 즐거움, 영감 그리고 재미를 선사합니다.`,
  NH = `이 게임은 굳은 의지와 인내심에 보답하는 게임으로, 실의에 잘 빠지는 사람을 위한 것은 아닙니다. 이 게임은 우리가 사랑한 역대 초고난도의 게임입니다.`,
  PH = `주목받아 마땅한 이 게임은 뛰어난 사운드트랙으로 인정받아야 합니다. 최고의 OST입니다! `,
  FH = `이야기가 풍부한 게임만이 여러분을 만족시키는 날도 있죠. 이 게임이 바로 그런 게임입니다. 드라마처럼 우리의 시선을 사로잡고, 명성 있는 TV쇼처럼 잘 짜여 있습니다. 브라비시모! 저희에게 감동을 선사해 주셔서 감사합니다!`,
  IH = `이 게임은 바쁜 일상에 단비와도 같은 게임입니다. 잔잔하고 편안하며 모든 걱정을 녹여줄 것입니다. 이 게임은 당신에게 휴식을 선물할 것입니다.`,
  LH = `이 게임은 너무 훌륭해서 어디서나 즐기고 싶은 게임이었죠. 그리고 정말로 장소에 구애받지 않고 플레이할 수 있게 되었습니다! 책상에서 플레이를 멈출 수 없었던 이 게임을 어디서든지 플레이할 수 있게 되었으니 더 훌륭해졌다고 말할 수밖에 없겠네요.`,
  RH = `VR 전용`,
  zH = `VR 지원`,
  BH = `다음 무작위 추첨까지 %1$s 남았습니다!`,
  VH = `다음 무작위 추첨까지 남은 시간.`,
  HH = `계속 시청하고 당첨 기회를 잡으세요!`,
  UH = `무작위 추첨 진행 중`,
  WH = `지금까지의 당첨자 수!`,
  GH = `무료 증정이 종료되었습니다. 참여해 주셔서 감사합니다.`,
  KH = `총 %1$s명의 당첨자와 함께 무료 증정이 종료되었습니다. 참여해 주셔서 감사합니다.`,
  qH = `보상, 당첨자 및 규칙에 대한 자세한 정보를 보려면 클릭하세요`,
  JH = `매일 돌아와 옥황상제의 새로운 선물을 받으세요!`,
  YH = `매일 새로운 챕터를 확인하세요`,
