  uU = `토큰 %1$s개`,
  dU = `봉투를 열 수 없습니다`,
  fU = `옥황상제의 위대한 경주`,
  pU = `12간지 띠 순서와 유래`,
  mU = `첫 번째 챕터`,
  hU = `두 번째 챕터`,
  gU = `세 번째 챕터`,
  _U = `네 번째 챕터`,
  vU = `옥황상제가 왕국의 모든 동물들을 소환하여, 천상까지의 경주에서 제일 먼저 도착하는 열두 마리의 동물은 새로운 달력에 실리는 영광을 누리게 될 것이라 선언했습니다.

천상에 제일 먼저 도착한 것은 영리한 쥐였습니다. 수영을 좋아하지 않는 쥐는, 믿음직한 황소의 등에 올라탄 뒤 황소가 육지에 도착하기 직전에 옥황상제의 하늘 정원으로 신나게 뛰어 들어갔습니다.

쉽게 강을 건넌 차분한 황소는 경주 결과에 연연하지 않았고, 쥐의 성공에 도움을 준 자신의 역할에 만족했습니다.`,
  yU = `자립심이 강한 호랑이는 너무 조심스럽게 움직인 나머지 황소를 앞지르지 못하고 세 번째로 도착했지만, 더 늦게 도착하는 것보단 낫다고 생각했습니다.

통나무에 올라탄 재빠른 토끼는 물 위에 둥둥 떠서는 어디에도 빨리 갈 수 없다는 것을 깨달았습니다. 하지만 전략이 통하지 않는 곳에서 행운이 찾아왔고, 불어오는 산들바람 덕분에 안전하게 목적지까지 도착할 수 있었습니다.

날개 달린 용은 그 능력으로 어려움에 처한 사람들을 도왔고, 도움을 줄 수 있는 곳이면 뭐든지 하기 위해 이동을 멈췄습니다. 심지어 토끼가 강을 건널 수 있도록 세찬 바람도 선물했죠. 승리보다 명예가 더 중요했던 용에게는 5위가 아주 잘 어울립니다.`,
  bU = `꿈틀꿈틀 은밀하게 움직이는 뱀은 장거리를 이동하기 위한 노력에는 거의 관심이 없었기 때문에, 말 앞발굽에 몰래 몸을 감았습니다.

 말이 결승선을 향해 말발굽을 달리자, 뱀은 똬리를 풀어 말을 깜짝 놀라게 하면서 뛰어내렸습니다. 놀란 말은 겨우 뱀의 뒤를 바짝 쫓아 6위를 차지했습니다.`,
  xU = `양과 원숭이와 닭은 함께 노력했지만, 그중에서 양이 그 여정을 주도하여 8위를 차지했습니다. 원숭이는 9위를 차지했고, 거드름 피우는 닭은 이 순서가 공정하다고 자랑스러워하며 10위를 받아들였습니다. 

장난기 넘치는 개는 물을 튀기며 수영하는 데 더 관심이 있었고, 경주가 재미있었기 때문에 11위를 차지한 것에 만족스러워합니다.

그리고 각 동물에게 옥황상제와 보낼 시간이 주어질 거란 걸 알만큼 똑똑한 돼지는 여행 도중에 먹고 자고 하다가 12번째로 도착했습니다.`,
  SU = `프로필 변경 사항은 검토 후 적용됩니다`,
  CU = `© %1$s Valve Corporation. 모든 권리 보유. 모든 상표는 미국 및 기타 국가에서 각각 해당 소유자의 재산입니다.`,
